MOD = 10**9 + 7

def fib(n: int) -> int:
    def go(k):
        # returns (F(k), F(k+1)) mod MOD
        if k == 0:
            return 0, 1
        a, b = go(k >> 1)              # a = F(m), b = F(m+1), m = k // 2
        c = a * ((2 * b - a) % MOD) % MOD   # F(2m)
        d = (a * a + b * b) % MOD           # F(2m+1)
        return (d, (c + d) % MOD) if k & 1 else (c, d)
    return go(n)[0]

int rob(const vector<int>& a) {
    int take = 0, skip = 0;   // best so far if house i-1 was robbed / not robbed
    for (int x : a) {
        int newTake = skip + x;
        skip = max(skip, take);
        take = newTake;
    }
    return max(take, skip);
}

def rob_circle(nums: list[int]) -> int:
    def line(arr):
        take, skip = 0, 0
        for x in arr:
            take, skip = skip + x, max(skip, take)
        return max(take, skip)
    if len(nums) == 1:
