    # first and last are neighbours: drop one of them
    return max(line(nums[:-1]), line(nums[1:]))

int minPathSum(const vector<vector<int>>& g) {
    int m = g.size(), n = g[0].size();
    vector<int> dp(n, INT_MAX);   // dp[j] = min cost to reach (i, j)
    dp[0] = 0;
    for (int i = 0; i < m; ++i) {
        dp[0] += g[i][0];
        for (int j = 1; j < n; ++j)
            dp[j] = min(dp[j], dp[j - 1]) + g[i][j];   // from above / from left
    }
    return dp[n - 1];
}

