int maximalSquare(const vector<vector<char>>& g) {
    int m = g.size(), n = g[0].size(), best = 0;
    vector<int> dp(n + 1, 0);       // dp[j+1] = side of largest square ending at (i, j)
    for (int i = 0; i < m; ++i) {
        int diag = 0;               // dp value of (i-1, j-1)
        for (int j = 0; j < n; ++j) {
            int up = dp[j + 1];
            dp[j + 1] = g[i][j] == '1' ? 1 + min({up, dp[j], diag}) : 0;
            diag = up;
            best = max(best, dp[j + 1]);
        }
    }
    return best * best;
}

string longestPalindrome(const string& s) {
    int bestL = 0, bestLen = 0, n = s.size();
    auto expand = [&](int l, int r) {
        while (l >= 0 && r < n && s[l] == s[r]) { --l; ++r; }
        if (r - l - 1 > bestLen) { bestLen = r - l - 1; bestL = l + 1; }
    };
    for (int c = 0; c < n; ++c) {
        expand(c, c);       // odd length, center at s[c]
        expand(c, c + 1);   // even length, center between c and c+1
    }
    return s.substr(bestL, bestLen);
}

int coinChange(const vector<int>& coins, int amount) {
    const int INF = amount + 1;            // more than any valid answer
    vector<int> dp(amount + 1, INF);
    dp[0] = 0;
    for (int a = 1; a <= amount; ++a)
        for (int c : coins)
            if (c <= a) dp[a] = min(dp[a], dp[a - c] + 1);
    return dp[amount] == INF ? -1 : dp[amount];
}

def word_break(s: str, words: list[str]) -> bool:
    vocab = set(words)
    max_len = max(map(len, words), default=0)
    ok = [False] * (len(s) + 1)
    ok[0] = True                  # empty prefix
    for i in range(1, len(s) + 1):
        for j in range(max(0, i - max_len), i):
            if ok[j] and s[j:i] in vocab:
                ok[i] = True
                break
    return ok[len(s)]

int minDistance(const string& a, const string& b) {
    int m = a.size(), n = b.size();
    vector<int> dp(n + 1);
    iota(dp.begin(), dp.end(), 0);         // row 0: j insertions
    for (int i = 1; i <= m; ++i) {
        int diag = dp[0];                  // dp[i-1][j-1]
        dp[0] = i;                         // column 0: i deletions
        for (int j = 1; j <= n; ++j) {
            int up = dp[j];                // dp[i-1][j]
            if (a[i - 1] == b[j - 1]) dp[j] = diag;
            else dp[j] = 1 + min({diag, up, dp[j - 1]});
            diag = up;
        }
    }
    return dp[n];
}

int longestCommonSubsequence(string a, string b) {
    if (a.size() < b.size()) swap(a, b);      // b = the shorter string
    int n = b.size();
    vector<int> dp(n + 1, 0);                 // dp[j] = LCS(prefix of a, b[0..j))
    for (char c : a) {
        int diag = 0;                         // dp[i-1][j-1]
        for (int j = 1; j <= n; ++j) {
            int up = dp[j];                   // dp[i-1][j]
            dp[j] = (c == b[j - 1]) ? diag + 1 : max(up, dp[j - 1]);
            diag = up;
        }
    }
    return dp[n];
}

int minDifficulty(const vector<int>& jobs, int d) {
    int n = jobs.size();
    if (n < d) return -1;                     // every day needs a job
    const int INF = INT_MAX / 2;
    vector<int> dp(n + 1, INF), nd(n + 1);    // dp[i]: first i jobs
    dp[0] = 0;
    for (int k = 1; k <= d; ++k) {
        fill(nd.begin(), nd.end(), INF);
        for (int i = k; i <= n; ++i) {
            int mx = 0;
            for (int j = i - 1; j >= k - 1; --j) {  // day k = jobs[j..i-1]
                mx = max(mx, jobs[j]);
                nd[i] = min(nd[i], dp[j] + mx);
            }
        }
        swap(dp, nd);
    }
    return dp[n];
}

string shortestCommonSupersequence(const string& a, const string& b) {
    int m = a.size(), n = b.size();
    // L[i][j] = LCS of the suffixes a[i..] and b[j..]
    vector<vector<int>> L(m + 1, vector<int>(n + 1, 0));
    for (int i = m - 1; i >= 0; --i)
        for (int j = n - 1; j >= 0; --j)
            L[i][j] = a[i] == b[j] ? L[i + 1][j + 1] + 1
                                   : max(L[i + 1][j], L[i][j + 1]);
    string r;
    int i = 0, j = 0;
    while (i < m && j < n) {
        if (a[i] == b[j]) { r += a[i]; ++i; ++j; }        // shared, once
        else if (L[i + 1][j] >= L[i][j + 1]) r += a[i++]; // a[i] not in LCS
        else r += b[j++];
    }
    return r + a.substr(i) + b.substr(j);
}

def num_squares(n: int) -> int:
    dp = [0] + [n] * n           # n ones is always an upper bound
    for a in range(1, n + 1):
        r = 1
        while r * r <= a:
            dp[a] = min(dp[a], dp[a - r * r] + 1)
            r += 1
    return dp[n]

int countSubstrings(const string& s) {
    int n = s.size(), cnt = 0;
    for (int c = 0; c < 2 * n - 1; ++c) {     // n char centers + n-1 gaps
        int l = c / 2, r = l + c % 2;
        while (l >= 0 && r < n && s[l] == s[r]) {
            ++cnt;                            // s[l..r] is a palindrome
            --l; ++r;
        }
    }
    return cnt;
}

bool isInterleave(const string& s1, const string& s2, const string& s3) {
    int m = s1.size(), n = s2.size();
    if (m + n != (int)s3.size()) return false;
    vector<char> dp(n + 1, false);   // row i: s1[0..i) + s2[0..j) -> s3[0..i+j)
    for (int i = 0; i <= m; ++i)
        for (int j = 0; j <= n; ++j) {
            if (i == 0 && j == 0) { dp[0] = true; continue; }
            bool v = false;
            if (i > 0 && dp[j] && s1[i - 1] == s3[i + j - 1]) v = true;     // from above
            if (j > 0 && dp[j - 1] && s2[j - 1] == s3[i + j - 1]) v = true; // from left
            dp[j] = v;
        }
    return dp[n];
}

