int longestArithSeqLength(const vector<int>& a) {
    int n = a.size();
    if (n <= 2) return n;
    const int OFF = 500;             // diff in [-500, 500]
    // dp[i][d + OFF] = longest arithmetic subsequence ending at i with diff d
    vector<vector<int>> dp(n, vector<int>(2 * OFF + 1, 1));
    int best = 2;
    for (int i = 1; i < n; ++i)
        for (int j = 0; j < i; ++j) {
            int d = a[i] - a[j] + OFF;
            dp[i][d] = max(dp[i][d], dp[j][d] + 1);
            best = max(best, dp[i][d]);
        }
    return best;
}

int longestPalindromeSubseq(const string& s) {
    int n = s.size();
    if (n == 0) return 0;
    vector<int> dp(n, 0);            // row i: dp[j] = LPS(s[i..j])
    for (int i = n - 1; i >= 0; --i) {
        dp[i] = 1;
        int inner = 0;               // LPS(s[i+1..j-1]) from row i+1
        for (int j = i + 1; j < n; ++j) {
            int below = dp[j];       // LPS(s[i+1..j])
            dp[j] = s[i] == s[j] ? inner + 2 : max(below, dp[j - 1]);
            inner = below;
        }
    }
    return dp[n - 1];
}

int numDistinct(const string& s, const string& t) {
    int n = t.size();
    // dp[j] = number of ways to form t[0..j) from the prefix of s seen so far
    vector<unsigned long long> dp(n + 1, 0);
    dp[0] = 1;                       // empty t: exactly one way
    for (char c : s)
        for (int j = n; j >= 1; --j) // descending: each char of s used once
            if (t[j - 1] == c) dp[j] += dp[j - 1];
    return (int)dp[n];
}

int calculateMinimumHP(const vector<vector<int>>& g) {
    int m = g.size(), n = g[0].size();
    // need[j] = min HP when entering (i, j) to survive to the end
    vector<int> need(n + 1, INT_MAX);
    need[n - 1] = 1;                 // virtual cell below the princess
    for (int i = m - 1; i >= 0; --i)
        for (int j = n - 1; j >= 0; --j)
            need[j] = max(1, min(need[j], need[j + 1]) - g[i][j]);
    return need[0];
}

int maxCoins(vector<int> nums) {
    nums.insert(nums.begin(), 1);
    nums.push_back(1);
    int n = nums.size();
    // dp[i][j] = best from bursting all balloons strictly between i and j
    vector<vector<int>> dp(n, vector<int>(n, 0));
    for (int len = 2; len < n; ++len)
        for (int i = 0; i + len < n; ++i) {
            int j = i + len;
            for (int k = i + 1; k < j; ++k)   // k = LAST burst in (i, j)
                dp[i][j] = max(dp[i][j],
                               dp[i][k] + dp[k][j] + nums[i] * nums[k] * nums[j]);
        }
    return dp[0][n - 1];
}

int jobScheduling(const vector<int>& st, const vector<int>& en,
                  const vector<int>& pr) {
    int n = st.size();
    vector<int> idx(n);
    iota(idx.begin(), idx.end(), 0);
    sort(idx.begin(), idx.end(), [&](int a, int b) { return en[a] < en[b]; });
    vector<int> ends(n);
    for (int k = 0; k < n; ++k) ends[k] = en[idx[k]];
    vector<long long> dp(n + 1, 0);  // dp[k] = best using first k jobs by end
    for (int k = 0; k < n; ++k) {
        int i = idx[k];
        // p = number of jobs that end no later than job i starts
        int p = upper_bound(ends.begin(), ends.begin() + k, st[i]) - ends.begin();
        dp[k + 1] = max(dp[k], dp[p] + pr[i]);
    }
    return (int)dp[n];
}

int minimumDifference(const vector<int>& a) {
    int n = a.size() / 2;
    long long total = accumulate(a.begin(), a.end(), 0LL);
    vector<vector<long long>> L(n + 1), R(n + 1);  // subset sums by size
    for (int m = 0; m < (1 << n); ++m) {
        int c = __builtin_popcount(m);
        long long sl = 0, sr = 0;
        for (int b = 0; b < n; ++b)
            if (m >> b & 1) { sl += a[b]; sr += a[n + b]; }
        L[c].push_back(sl);
        R[c].push_back(sr);
    }
    for (auto& v : R) sort(v.begin(), v.end());
    long long best = LLONG_MAX;
    for (int c = 0; c <= n; ++c) {
        const auto& v = R[n - c];             // c left + (n-c) right = n
        for (long long x : L[c]) {
            long long T = total - 2 * x;      // minimize |T - 2y|
            auto it = partition_point(v.begin(), v.end(),
                                      [&](long long y) { return 2 * y < T; });
            if (it != v.end()) best = min(best, llabs(T - 2 * *it));
            if (it != v.begin()) best = min(best, llabs(T - 2 * *prev(it)));
        }
    }
    return (int)best;
}

def count_squares(grid: list[list[int]]) -> int:
    if not grid:
        return 0
    n = len(grid[0])
    prev = [0] * (n + 1)          # dp of the previous row, 1-based columns
    total = 0
    for row in grid:
        cur = [0] * (n + 1)
        for j in range(1, n + 1):
            if row[j - 1] == 1:
                cur[j] = 1 + min(prev[j], cur[j - 1], prev[j - 1])
                total += cur[j]   # cur[j] squares end at this corner
        prev = cur
    return total

def num_ways(n: int, k: int) -> int:
    if n == 0:
        return 0
    same, diff = 0, k            # post 1: nothing to repeat yet
    for _ in range(n - 1):
        # same: copy the previous color, allowed only after a 'diff' post
        same, diff = diff, (same + diff) * (k - 1)
    return same + diff

bool isValidPalindrome(const string& s, int k) {
    int n = s.size();
    if (n == 0) return true;
    // row i: dp[j] = min deletions that make s[i..j] a palindrome
    vector<int> dp(n, 0);
    for (int i = n - 2; i >= 0; --i) {
        int inner = 0;               // dp[i+1][j-1] (empty or 1 char -> 0)
        for (int j = i + 1; j < n; ++j) {
            int below = dp[j];       // dp[i+1][j]
            dp[j] = s[i] == s[j] ? inner : 1 + min(below, dp[j - 1]);
            inner = below;
        }
    }
    return dp[n - 1] <= k;
}

from functools import lru_cache

def possibly_equals(s1: str, s2: str) -> bool:
    n1, n2 = len(s1), len(s2)

    @lru_cache(maxsize=None)
    def go(i, j, diff):
        # diff > 0: s2 has diff unmatched wildcards; diff < 0: s1 has -diff
        if i == n1 and j == n2:
            return diff == 0
        if i < n1 and s1[i].isdigit():          # every split of s1's number
            val, p = 0, i
            while p < n1 and s1[p].isdigit():
                val = val * 10 + int(s1[p]); p += 1
                if go(p, j, diff - val):
                    return True
            return False
        if j < n2 and s2[j].isdigit():          # every split of s2's number
            val, q = 0, j
            while q < n2 and s2[q].isdigit():
                val = val * 10 + int(s2[q]); q += 1
                if go(i, q, diff + val):
                    return True
            return False
        if diff > 0:                             # s1 letter vs s2 wildcard
            return i < n1 and go(i + 1, j, diff - 1)
        if diff < 0:                             # s2 letter vs s1 wildcard
            return j < n2 and go(i, j + 1, diff + 1)
        return i < n1 and j < n2 and s1[i] == s2[j] and go(i + 1, j + 1, 0)

    return go(0, 0, 0)

