def minimum_deletions(s: str) -> int:
    dels = 0                 # answer for the prefix so far
    b_seen = 0
    for c in s:
        if c == 'b':
            b_seen += 1      # a trailing 'b' never breaks balance
        else:
            # delete this 'a', or keep it and delete every 'b' so far
            dels = min(dels + 1, b_seen)
    return dels

long long numTrees(int n) {
    vector<long long> g(n + 1, 0);
    g[0] = 1;                                          // עץ ריק: מבנה אחד
    for (int nodes = 1; nodes <= n; ++nodes)
        for (int root = 1; root <= nodes; ++root)      // root - 1 משמאל, nodes - root מימין
            g[nodes] += g[root - 1] * g[nodes - root];
    return g[n];                                       // מספר קטלן; long long מספיק עד n = 35
}

double champagneTower(int poured, int queryRow, int queryGlass) {
    vector<double> row{(double)poured};               // כמה זרם לכל כוס בשורה הנוכחית
    for (int r = 0; r < queryRow; ++r) {
        vector<double> next(r + 2, 0.0);
        for (int i = 0; i <= r; ++i) {
            double excess = max(0.0, row[i] - 1.0);    // הכוס מחזיקה 1; העודף נשפך
            next[i] += excess / 2;
            next[i + 1] += excess / 2;
        }
        row = move(next);
    }
    return min(1.0, row[queryGlass]);                  // מה שזרם לכוס, חסום בקיבולת
}

// כל קואורדינטות הצפון שונות זו מזו, וכל קואורדינטות הדרום שונות זו מזו
int maxBridges(vector<pair<int, int>> b) {            // (north, south)
    sort(b.begin(), b.end());                          // לפי north
    vector<int> tails;                                 // tails[k] = הסוף הקטן ביותר של רצף עולה באורך k+1
    for (auto& [north, south] : b) {
        auto it = lower_bound(tails.begin(), tails.end(), south);   // עולה ממש
        if (it == tails.end()) tails.push_back(south);
        else *it = south;
    }
    return tails.size();                               // LIS על south
}

def longest_bitonic_subarray(a):
    """אורך תת-המערך הרציף הארוך ביותר שעולה (לא יורד) ואז יורד (לא עולה)."""
    n = len(a)
    if n == 0:
        return 0
    inc = [1] * n                     # אורך הרצף הלא-יורד שמסתיים ב-i
    for i in range(1, n):
        if a[i] >= a[i - 1]:
            inc[i] = inc[i - 1] + 1
    dec = [1] * n                     # אורך הרצף הלא-עולה שמתחיל ב-i
    for i in range(n - 2, -1, -1):
        if a[i] >= a[i + 1]:
            dec[i] = dec[i + 1] + 1
    return max(inc[i] + dec[i] - 1 for i in range(n))   # i הוא השיא

bool subsetSum(const vector<int>& nums, int target) {   // nums אי-שליליים
    vector<char> can(target + 1, 0);                   // can[s]: אפשר להגיע לסכום s
    can[0] = 1;
    for (int x : nums)
        for (int s = target; s >= x; --s)              // מלמעלה למטה: כל איבר פעם אחת
            if (can[s - x]) can[s] = 1;
    return can[target];
}

