// הערך בשורה i ועמודה j של משולש פסקל (0-based), כלומר C(i, j)
long long pascalValue(int i, int j) {
    if (j < 0 || j > i) return 0;
    j = min(j, i - j);                                 // סימטריה: פחות צעדים
    long long result = 1;
    for (int k = 0; k < j; ++k)
        result = result * (i - k) / (k + 1);           // תמיד מתחלק: זה C(i, k+1)·(k+1)
    return result;
}

long long maxPoints(const vector<vector<int>>& p) {
    int m = p.size(), n = p[0].size();
    vector<long long> dp(p[0].begin(), p[0].end()), left(n), right(n);
    for (int r = 1; r < m; ++r) {
        left[0] = dp[0];
        for (int j = 1; j < n; ++j) left[j] = max(left[j - 1] - 1, dp[j]);
        right[n - 1] = dp[n - 1];
        for (int j = n - 2; j >= 0; --j) right[j] = max(right[j + 1] - 1, dp[j]);
        for (int j = 0; j < n; ++j) dp[j] = p[r][j] + max(left[j], right[j]);
    }
    return *max_element(dp.begin(), dp.end());
}

int numWays(int steps, int arrLen) {
    const int MOD = 1'000'000'007;
    int w = min(arrLen, steps / 2 + 1);
    vector<long long> dp(w, 0), nd(w);
    dp[0] = 1;
    for (int s = 0; s < steps; ++s) {
        for (int i = 0; i < w; ++i) {
            long long v = dp[i];
            if (i > 0) v += dp[i - 1];
            if (i + 1 < w) v += dp[i + 1];
            nd[i] = v % MOD;
        }
        swap(dp, nd);
    }
    return dp[0];
}

