def ways(steps, n):
    w = min(n, steps // 2 + 1)
    dp = [1] + [0] * (w - 1)
    for _ in range(steps):
        for i in range(w):
            left = dp[i - 1] if i > 0 else 0
            right = dp[i + 1] if i + 1 < w else 0
            dp[i] = (dp[i] + left + right) % MOD
    return dp[0]

