from functools import lru_cache

def longest_increasing_path(m):
    if not m or not m[0]:
        return 0
    rows, cols = len(m), len(m[0])

    @lru_cache(maxsize=None)
    def best(r, c):                          # longest path starting at (r, c)
        res = 1
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and m[nr][nc] > m[r][c]:
                res = max(res, 1 + best(nr, nc))
        return res

    return max(best(r, c) for r in range(rows) for c in range(cols))
